WITH windows AS (SELECT 0 AS sample, 19777 AS pid, 10548100000000 AS start_ns, 10549837333458 AS end_ns UNION ALL SELECT 1 AS sample, 19777 AS pid, 10550720000000 AS start_ns, 10552386687083 AS end_ns UNION ALL SELECT 2 AS sample, 19777 AS pid, 10553180000000 AS start_ns, 10554842217833 AS end_ns UNION ALL SELECT 3 AS sample, 19777 AS pid, 10555600000000 AS start_ns, 10557249214875 AS end_ns UNION ALL SELECT 4 AS sample, 19777 AS pid, 10557990000000 AS start_ns, 10559655194458 AS end_ns UNION ALL SELECT 5 AS sample, 19777 AS pid, 10560490000000 AS start_ns, 10562133594083 AS end_ns UNION ALL SELECT 6 AS sample, 19777 AS pid, 10562940000000 AS start_ns, 10564582161209 AS end_ns UNION ALL SELECT 7 AS sample, 19777 AS pid, 10565350000000 AS start_ns, 10566995481458 AS end_ns UNION ALL SELECT 8 AS sample, 19777 AS pid, 10567810000000 AS start_ns, 10569462525332 AS end_ns UNION ALL SELECT 9 AS sample, 19777 AS pid, 10570450000000 AS start_ns, 10572236647917 AS end_ns UNION ALL SELECT 10 AS sample, 19777 AS pid, 10573290000000 AS start_ns, 10574951059250 AS end_ns UNION ALL SELECT 11 AS sample, 19777 AS pid, 10575730000000 AS start_ns, 10577385537166 AS end_ns UNION ALL SELECT 12 AS sample, 19777 AS pid, 10578130000000 AS start_ns, 10579810291249 AS end_ns UNION ALL SELECT 13 AS sample, 19777 AS pid, 10580660000000 AS start_ns, 10582316124416 AS end_ns UNION ALL SELECT 14 AS sample, 19777 AS pid, 10583140000000 AS start_ns, 10584791288209 AS end_ns UNION ALL SELECT 15 AS sample, 19777 AS pid, 10585670000000 AS start_ns, 10587337779541 AS end_ns UNION ALL SELECT 16 AS sample, 19777 AS pid, 10588180000000 AS start_ns, 10589844324082 AS end_ns UNION ALL SELECT 17 AS sample, 19777 AS pid, 10590720000000 AS start_ns, 10592421880875 AS end_ns UNION ALL SELECT 18 AS sample, 19777 AS pid, 10593290000000 AS start_ns, 10594945213458 AS end_ns UNION ALL SELECT 19 AS sample, 19777 AS pid, 10595830000000 AS start_ns, 10597490712292 AS end_ns UNION ALL SELECT 20 AS sample, 19777 AS pid, 10598320000000 AS start_ns, 10599973799125 AS end_ns UNION ALL SELECT 21 AS sample, 19777 AS pid, 10600870000000 AS start_ns, 10602549476084 AS end_ns UNION ALL SELECT 22 AS sample, 19777 AS pid, 10603460000000 AS start_ns, 10605269009875 AS end_ns UNION ALL SELECT 23 AS sample, 19777 AS pid, 10606460000000 AS start_ns, 10608126513166 AS end_ns UNION ALL SELECT 24 AS sample, 19777 AS pid, 10608950000000 AS start_ns, 10610614380249 AS end_ns UNION ALL SELECT 25 AS sample, 19777 AS pid, 10611750000000 AS start_ns, 10613401505124 AS end_ns UNION ALL SELECT 26 AS sample, 19777 AS pid, 10614340000000 AS start_ns, 10615993737290 AS end_ns UNION ALL SELECT 27 AS sample, 19777 AS pid, 10616850000000 AS start_ns, 10618515307375 AS end_ns UNION ALL SELECT 28 AS sample, 19777 AS pid, 10619360000000 AS start_ns, 10621012697333 AS end_ns UNION ALL SELECT 29 AS sample, 19777 AS pid, 10621950000000 AS start_ns, 10623611595082 AS end_ns UNION ALL SELECT 30 AS sample, 19777 AS pid, 10624410000000 AS start_ns, 10626061603375 AS end_ns UNION ALL SELECT 31 AS sample, 19777 AS pid, 10626990000000 AS start_ns, 10628663015165 AS end_ns UNION ALL SELECT 32 AS sample, 19777 AS pid, 10629570000000 AS start_ns, 10631236231542 AS end_ns UNION ALL SELECT 33 AS sample, 19777 AS pid, 10632170000000 AS start_ns, 10633860287541 AS end_ns UNION ALL SELECT 34 AS sample, 19777 AS pid, 10634710000000 AS start_ns, 10636359740708 AS end_ns UNION ALL SELECT 35 AS sample, 19777 AS pid, 10637160000000 AS start_ns, 10638917088750 AS end_ns)
SELECT w.sample, count(*) AS app_frame_records,
 sum(CASE WHEN a.jank_type LIKE '%App Deadline Missed%' THEN 1 ELSE 0 END) AS app_deadline_misses,
 sum(CASE WHEN a.jank_type != 'None' THEN 1 ELSE 0 END) AS all_jank_records,
 sum(CASE WHEN a.present_type = 'Dropped Frame' THEN 1 ELSE 0 END) AS dropped_frame_records,
 round(avg(a.dur)/1e6,2) AS mean_actual_frame_ms,
 round(max(a.dur)/1e6,2) AS max_actual_frame_ms,
 group_concat(a.dur) AS actual_durations_ns
FROM windows w JOIN process p ON p.pid=w.pid
JOIN actual_frame_timeline_slice a ON a.upid=p.upid
WHERE a.ts >= w.start_ns AND a.ts < w.end_ns AND a.dur > 0
GROUP BY w.sample ORDER BY w.sample